effect.shader:
#define PI  3.14159265359
vec4 sampleTex(vec2 uv){
if(clampEdges){
uv = clamp(uv, 0.0, 1.0);
}
return texture2DCv(inputImg.texture, uv);
}
float weightGaussian(float t, float fo){
float sigma = 0.4 / max(fo, 0.01);
return exp(-(t*t) / (2.0*sigma*sigma));
}
float weightLinear(float t, float fo){
return max(0.0, 1.0 - abs(t) * fo);
}
float weightBox(float t){
return 1.0;
}
float weightSinc(float t, float fo){
if(abs(t) < 0.001) return 1.0;
float x = t * fo * PI * 2.5;
float sinc = sin(x) / x;
float lx = t * fo * PI;
float window = (abs(lx) < PI) ? (sin(lx)/lx) : 0.0;
return clamp(sinc * window, 0.0, 1.0);
}
float getWeight(float t){
if(blurShape==0) return weightGaussian(t, falloff);
if(blurShape==1) return weightLinear(t, falloff);
if(blurShape==2) return weightBox(t);
return weightSinc(t, falloff);
}
vec4 blurSample(vec2 uv, vec2 blurVec, float halfLen,
float sampleCount, int side){
vec4  acc   = vec4(0.0);
float wsum  = 0.0;
float N     = sampleCount;
float thinStep = 1.0 + thin * 3.0;
for(float i = 0.0; i < 64.0; i += 1.0){
if(i >= N) break;
if(mod(i, max(thinStep, 1.0)) > 0.5 && i > 0.0) continue;
float t = (N <= 1.0) ? 0.0 : i / (N - 1.0);
float signedT;
if(side == 0){
signedT = t * 2.0 - 1.0;
} else if(side == 1){
signedT = t;
} else {
signedT = -t;
}
if(spread > 0.001){
signedT = sign(signedT) * pow(abs(signedT), 1.0 - spread * 0.7);
}
vec2 offset = blurVec * signedT * halfLen;
vec2 sampleUV;
if(displacePixels){
sampleUV = uv + blurVec * halfLen + offset;
} else {
sampleUV = uv + offset;
}
vec4  s = sampleTex(sampleUV);
float w = getWeight(signedT);
acc   += s * w;
wsum  += w;
}
return (wsum > 0.0) ? acc / wsum : sampleTex(uv);
}
void main(){
vec2 uv     = acScreenNorm;
vec4 orig   = texture2DCv(inputImg.texture, uv);
vec2 res    = acScreenSize;
if(blurLength < 0.1){
gl_FragColor = orig;
return;
}
float dirRad  = direction * PI / 180.0;
vec2  blurDir = vec2(cos(dirRad), -sin(dirRad));
float halfLen = (blurLength * 0.5) / res.x;
float radMask = 1.0;
if(radialFalloff > 0.001){
vec2  ctr  = vec2(centerX, centerY);
float dist = length((uv - ctr) * vec2(1.0, res.y/res.x));
radMask = 1.0 - smoothstep(0.0, radialFalloff, dist);
radMask = clamp(radMask, 0.0, 1.0);
}
vec4  blurred = vec4(0.0);
float totalW  = 0.0;
int   spreadSteps = (angleSpread > 0.5) ? 3 : 1;
float spreadRad   = angleSpread * PI / 180.0;
for(int ai = 0; ai < 3; ai++){
if(ai >= spreadSteps) break;
float aOffset = 0.0;
if(spreadSteps == 3){
aOffset = (float(ai) - 1.0) * spreadRad * 0.5;
}
float ang = dirRad + aOffset;
vec2  bv  = vec2(cos(ang), -sin(ang));
float angleW = (ai == 1) ? 0.5 : 1.0;
blurred += blurSample(uv, bv, halfLen, samples, sideMode) * angleW;
totalW  += angleW;
}
blurred /= max(totalW, 0.001);
if(radialFalloff > 0.001){
blurred = mix(orig, blurred, radMask);
}
if(threshold > 0.001){
float origL   = dot(orig.rgb, vec3(0.299,0.587,0.114));
float blurL   = dot(blurred.rgb, vec3(0.299,0.587,0.114));
float diff    = abs(origL - blurL);
float tMask   = smoothstep(0.0, threshold, diff);
blurred = mix(orig, blurred, tMask);
}
vec4 result = mix(orig, blurred, mixAmount);
vec3 origRGB   = orig.rgb   / max(orig.a,   0.001);
vec3 resultRGB = result.rgb / max(result.a, 0.001);
if(blendMode == 1){
resultRGB = origRGB + resultRGB;
} else if(blendMode == 2){
resultRGB = 1.0-(1.0-origRGB)*(1.0-resultRGB);
} else if(blendMode == 3){
resultRGB = origRGB * resultRGB;
}
resultRGB = clamp(resultRGB, 0.0, 1.0);
gl_FragColor = vec4(resultRGB, orig.a) * orig.a;
}
